import {ERA_BOUNDS,DURATIONS,SCIENCES,DEFAULT_STATE,languageOf,filterWorks,stateFromURL,searchFromState} from './model.mjs';
import {mountUniverse} from './universe.mjs';
import {mountChronology} from './chronology.mjs?v=round4-context';
import {mountBibliography} from './bibliography.mjs';
import {mountTaxonomy} from './taxonomy.mjs';
import {buildCanonicalUniverse,coverageOf,FIELD_LABELS} from './canonical.mjs?v=round49-single-pass';
import {issueDetail,renderIssueExplorer} from './issues.mjs?v=round49-single-pass';
import {completionDetail,renderCompletion} from './completion.mjs?v=round49-single-pass';
import {loadBibliographySource,loadSourceDetail,loadCompletionSource,loadLibraryDetail} from './data-loader.mjs';
const $=id=>document.getElementById(id);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unique=arr=>[...new Set(arr)].sort((a,b)=>a.localeCompare(b,'zh-CN'));
const PAGE_SIZE=18;const SITE_DEFAULT_STATE={...DEFAULT_STATE,boundary:true};
let universe,chronology,bibliography,taxonomy,spatial={},spatialById=new Map(),currentView='universe';
let genreGraph=null;let aliases=new Map(),sourceMetadata={},allCoverage={},detailTicket=0;
let works=[],content={},byId=new Map(),state={...SITE_DEFAULT_STATE},selectedWork='',compareIds=[],toastTimer;
const viewNames=['universe','chronology','bibliography','taxonomy','library','history','themes','routes','method','completion'];
const filterNames={topic:'议题',branch:'分支',era:'年代',duration:'跨度',science:'科学前提',language:'语言',form:'形态'};
const tag=(label,key='topic')=>`<button class="tag${key==='branch'?' neutral':''}" data-filter="${key}" data-value="${escape(label)}">${escape(label)}</button>`;
const compareButton=w=>`<button class="compare-button" data-compare="${w.id}" aria-pressed="${compareIds.includes(w.id)}" aria-label="${compareIds.includes(w.id)?'从比较移除':'加入比较'}：${escape(w.title_zh)}">${compareIds.includes(w.id)?'✓ 已加入比较':'+ 比较'}</button>`;
const anchor=id=>{id=aliases.get(id)||id;const w=byId.get(id);return w?`<button class="anchor-link" data-work="${id}">${escape(w.title_zh)}<small>${escape(w.year_display)}</small></button>`:'';};
function setOptions(id,options){$(id).insertAdjacentHTML('beforeend',options.map(item=>{const o=typeof item==='string'?{id:item,label:item}:item;return `<option value="${escape(o.id)}">${escape(o.label)}</option>`;}).join(''));}
function updateURL(){const search=searchFromState(state,selectedWork);history.replaceState(null,'',location.pathname+(search?'?'+search:'')+(location.hash||'#universe'));}
function readComparison(){try{const ids=JSON.parse(localStorage.getItem('sf-atlas-comparison')||'[]');return Array.isArray(ids)?unique(ids.map(id=>aliases.get(id)||id).filter(id=>byId.has(id))).slice(0,3):[];}catch{return [];}}
function saveComparison(){try{localStorage.setItem('sf-atlas-comparison',JSON.stringify(compareIds));}catch{}}
function updateFilters(){for(const key of ['level','space','yearStatus','audit','missing','issueStatus','facet'])$(`global-${key}`).value=state[key];$('global-search').value=state.query;for(const key of Object.keys(filterNames))$(`filter-${key}`).value=state[key];$('search-input').value=state.query;$('include-boundary').checked=state.boundary;$('chronology-boundary').checked=state.boundary;$('sort').value=state.sort;}
function syncVisuals(){
 const filtered=filterWorks(works,state);
 const scopeSelections=Object.entries(state).filter(([key,value])=>value&&['query','topic','branch','duration','science','language','form','level','space','genre','type','audit','missing','issueStatus','facet','yearStatus','era'].includes(key)).map(([key,value])=>{const control=$(`global-${key}`)||$(`filter-${key}`);return `${({query:'搜索',level:'研究层级',space:'空间',yearStatus:'年份状态',audit:'核对状态',missing:'缺失字段',issueStatus:'议题分析',facet:'细分议题',genre:'来源分支',type:'来源类型',...filterNames})[key]}：${control?.selectedOptions?.[0]?.textContent||value}`;});
 universe?.update(filtered,state.topic);universe?.setZone(state.space||'all');
 chronology?.update(filterWorks(works,{...state,yearMin:null,yearMax:null}),{works:filterWorks(works,{...DEFAULT_STATE,boundary:state.boundary}),label:scopeSelections.length?`当前条件：${scopeSelections.join('；')}`:'当前条件：全部记录'});
 if(state.yearStatus==='unknown')chronology?.setUnknown();else chronology?.setRange(state.yearMin,state.yearMax);
 bibliography?.update(filtered,sourceMetadata,state,works);if(genreGraph)taxonomy?.update(genreGraph,filtered);
 $('chronology-filter-status').textContent=`当前匹配 ${filtered.length.toLocaleString('zh-CN')} / 底库 ${works.length.toLocaleString('zh-CN')} 条${state.space?` · 空间：${$('global-space').selectedOptions[0]?.textContent}`:''}；所有视图共用筛选。`;
 renderThemes(filtered);
 $('global-count').textContent=`${filtered.length.toLocaleString('zh-CN')} / ${works.length.toLocaleString('zh-CN')} 条`;
 $('global-active').innerHTML=Object.entries(state).filter(([key,value])=>value&&['query','level','space','yearStatus','topic','branch','era','duration','science','language','form','genre','type','yearMin','yearMax','audit','missing','issueStatus','facet'].includes(key)).map(([key,value])=>{const control=$(`global-${key}`)||$(`filter-${key}`);const label=key==='missing'?FIELD_LABELS[value]:control?.selectedOptions?.[0]?.textContent||value;const prefix=({query:'搜索：',level:'研究层级：',space:'空间：',yearStatus:'年份状态：'})[key]||'';return `<button data-clear="${key}" aria-label="移除筛选：${escape(prefix+label)}">${escape(prefix+label)} ×</button>`;}).join('');
}
function renderLibrary(){
 const filtered=filterWorks(works,state),pageCount=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));
 state.page=Math.min(state.page,pageCount);const start=(state.page-1)*PAGE_SIZE,page=filtered.slice(start,start+PAGE_SIZE);
 $('result-count').innerHTML=`<strong>${filtered.length}</strong> 条结果 <span>／ ${filterWorks(works,{...DEFAULT_STATE,boundary:state.boundary}).length} 条${'统一记录'}</span>`;
 $('active-filters').innerHTML=Object.keys(filterNames).filter(key=>state[key]).map(key=>`<button data-clear="${key}" aria-label="移除${filterNames[key]}筛选：${escape(state[key])}">${escape(key==='era'?ERA_BOUNDS.find(e=>e.id===state.era)?.label:state[key])} <span aria-hidden="true">×</span></button>`).join('');
 if(state.yearMin!=null||state.yearMax!=null)$('active-filters').insertAdjacentHTML('beforeend',`<button data-clear-years aria-label="移除发表年份范围筛选">发表年份 ${state.yearMin??'最早'}—${state.yearMax??'最新'} <span aria-hidden="true">×</span></button>`);
 $('cards-toggle').setAttribute('aria-pressed',String(state.layout==='cards'));$('table-toggle').setAttribute('aria-pressed',String(state.layout==='table'));
 if(!filtered.length){$('results').innerHTML='<div class="empty-state"><h3>这组条件暂时没有作品</h3><p>试着移除一个筛选，或用更短的关键词搜索。</p><button data-reset>重置筛选</button></div>';}
 else if(state.layout==='cards')$('results').innerHTML=`<div class="work-grid">${page.map(w=>`<article class="work-card"><div class="card-top"><span class="card-year">${escape(w.year_display)}</span><span class="form-label">${w.research?'已有研究':w.knowledge?'知识补充 · 待核':w.topics.length?'议题候选':'基础书目'}</span></div><h3><button class="title-button" data-work="${w.id}">${escape(w.title_zh)}</button></h3><p class="card-author">${escape(w.author)}</p><p class="card-audit">待独立核对 · ${w.completion?.missing_fields.length||0} 个字段待补全${w.completion?.has_conflict?' · 存在日期差异':''}</p>${w.knowledge_identity_notes.length?'<p class="card-audit">题名／文本单位有疑点，详见分析备注</p>':''}<p class="card-question">${escape(w.issue)}</p><div class="tag-list">${w.topics.slice(0,2).map(t=>tag(t)).join('')||'<span>议题待分类</span>'}</div><div class="card-bottom"><span>${escape(w.duration)} · ${escape(w.science_class)}</span>${compareButton(w)}</div></article>`).join('')}</div>`;
 else $('results').innerHTML=`<div class="table-scroll"><table class="work-table"><thead><tr><th scope="col">作品 / 作者</th><th scope="col">发表年份</th><th scope="col">底层议题</th><th scope="col">叙事跨度</th><th scope="col">科学前提</th><th scope="col">比较</th></tr></thead><tbody>${page.map(w=>`<tr><td><button class="title-button" data-work="${w.id}">${escape(w.title_zh)}</button><small>${escape(w.author)}</small></td><td>${escape(w.year_display)}</td><td><div class="tag-list">${w.topics.map(t=>tag(t)).join('')}</div></td><td>${escape(w.duration)}</td><td>${escape(w.science_class)}</td><td>${compareButton(w)}</td></tr>`).join('')}</tbody></table></div>`;
 $('page-status').textContent=filtered.length?`${start+1}—${Math.min(start+PAGE_SIZE,filtered.length)} / ${filtered.length} · 第 ${state.page}/${pageCount} 页`:'0 条结果';
 $('previous-page').disabled=state.page<=1;$('next-page').disabled=state.page>=pageCount;
 updateURL();syncVisuals();
}
function renderNavigation(){
 if(viewNames.includes(location.hash.slice(1)))currentView=location.hash.slice(1);
 const view=currentView;
 for(const name of viewNames)$(`${name}-view`).hidden=name!==view;
 document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 document.title=`${({universe:'宇宙图景',chronology:'时间长廊',bibliography:'全景书目',taxonomy:'分支谱系',library:'研究目录',history:'历史脉络',themes:'议题地图',routes:'阅读路线',method:'研究方法',completion:'补全进度'})[view]} · 科幻文明图谱`;
}
function renderContent(){
 $('history-list').innerHTML=content.periods.map((period,i)=>`<article class="history-item"><div class="history-date">${escape(period.time_label)}<small>${String(i+1).padStart(2,'0')}</small></div><div><h3>${escape(period.title)}</h3><p>${escape(period.description)}</p><button class="browse-button" data-filter="era" data-value="${ERA_BOUNDS[i].id}">浏览这一时期全部 ${works.filter(w=>w.sort_year!=null&&w.sort_year>=ERA_BOUNDS[i].min&&w.sort_year<=ERA_BOUNDS[i].max).length} 条记录 →</button></div><div class="anchor-list">${period.anchor_work_ids.map(anchor).join('')}</div></article>`).join('');
 $('route-list').innerHTML=content.routes.map((route,i)=>`<article class="route-item"><div class="route-description"><span class="eyebrow">PATH ${String(i+1).padStart(2,'0')}</span><h3>${escape(route.title)}</h3><p>${escape(route.description)}</p><small>${route.work_ids.length} 条目录 · 可按问题调整次序</small></div><ol class="route-steps">${route.steps.map((step,index)=>`<li data-step="${index+1}"><h4>${escape(step.label)}${step.relationship?' · '+escape(step.relationship):''}</h4><div class="route-books">${step.work_ids.map(anchor).join('')}</div>${step.scope_note?`<p class="route-scope">${escape(step.scope_note)}</p>`:''}</li>`).join('')}</ol></article>`).join('');
}
function renderThemes(themeWorks){
 renderIssueExplorer($('issue-explorer'),themeWorks);
 $('theme-list').innerHTML=content.topics.map((topic,i)=>`<article class="theme-item"><div class="theme-top"><span>${String(i+1).padStart(2,'0')} / QUESTION</span><span>${themeWorks.filter(w=>w.research_topics.includes(topic.title)).length} 条研究 / ${themeWorks.filter(w=>w.knowledge_topics.includes(topic.title)).length} 条知识补充 / ${themeWorks.filter(w=>w.topic_candidates.some(t=>t.topic===topic.title)).length} 条候选</span></div><h3>${escape(topic.title)}</h3><p>${escape(topic.core_question)}</p><div class="theme-examples">${themeWorks.filter(w=>w.topics.includes(topic.title)&&w.issue_analysis_status!=='missing').slice(0,4).map(w=>anchor(w.id)).join('')}</div><button class="browse-button" data-filter="topic" data-value="${escape(topic.title)}">按这一议题浏览 →</button></article>`).join('');
 $('theme-list').insertAdjacentHTML('beforeend',`<article class="theme-item"><h3>保留尚未整理的问题</h3><p>${themeWorks.filter(w=>!w.topics.length).length.toLocaleString('zh-CN')} 条尚无议题分类；${themeWorks.filter(w=>w.issue_analysis_status==='missing').length.toLocaleString('zh-CN')} 条尚无作品分析。分类标签与核心问题分析分别登记。</p><button class="browse-button" data-filter="issueStatus" data-value="missing">浏览分析尚未补充的作品 →</button></article>`);
}
function safeSource(url){try{const u=new URL(url);return u.protocol==='https:'||u.protocol==='http:'?u:null;}catch{return null;}}
function sourceLabel(u){const host=u.hostname.replace(/^www\./,'');if(host==='sf-encyclopedia.com')return 'The Encyclopedia of Science Fiction · '+decodeURIComponent(u.pathname.split('/').pop()).replaceAll('_',' ');return host+' · 原始资料';}
function openWork(id){
 id=aliases.get(id)||id;const w=byId.get(id);if(!w)return;selectedWork=id;const ticket=++detailTicket;const place=spatialById.get(id),zone=spatial.zones?.find(z=>z.id===place?.primary);
 $('work-detail').innerHTML=`<span class="eyebrow">${w.research?'已有研究':w.knowledge?'知识补充 · 待核':w.topics.length?'来源议题候选':'基础书目'} / ${escape(w.id)}</span><h2 id="work-dialog-heading">${escape(w.title_zh)}</h2><p class="original-title">${escape(w.title_original)}</p><p class="detail-author">${escape(w.author)} · ${escape(w.language_tradition)}</p><div class="detail-question">${escape(w.issue)}</div>${issueDetail(w)}${place?`<div class="space-evidence"><strong>空间导航：${escape(zone?.label||'空间待分类')} · ${escape(place.confidence)}</strong><p>${escape(place.rationale)}</p><p>仅用于空间阅读导航，不是物理位置或距离。</p></div>`:''}<div class="detail-section"><h3>书目与时间</h3><dl><dt>当前时间轴纪年</dt><dd>${escape(w.year_display)}</dd><dt>来源最早年份候选</dt><dd>${escape(w.source_first_year??'未知')}</dd><dt>版本备注</dt><dd>${escape(w.year_note)}</dd><dt>故事所在时代</dt><dd>${escape(w.story_era)}</dd><dt>主体叙事跨度</dt><dd>${escape(w.duration)}</dd><dt>最大时间视野</dt><dd>${escape(w.reach)}</dd>${w.series_name?`<dt>系列</dt><dd>${escape(w.series_name)}</dd>`:''}</dl></div><div class="detail-section detail-tags"><h3>议题与分支</h3><div class="tag-list">${w.research_topics.map(t=>tag(t)).join('')||'研究议题未知'}</div>${w.knowledge_topics.length?`<p>已有知识补充（待独立核对）：${w.knowledge_topics.map(t=>tag(t)).join('')}</p>`:''}<p>来源规则候选：${escape(w.topic_candidates.map(t=>t.topic).join('、')||'无候选')}</p><div class="tag-list" style="margin-top:8px">${w.branches.map(b=>tag(b,'branch')).join('')}</div></div><div class="detail-section"><h3>科学前提 · ${escape(w.science_class)}</h3><p>${escape(w.science_note)}</p><p>这是关键设定与当前知识关系的定性分类，不是作品质量或未来预测准确率。</p></div><div class="detail-section"><h3>资料来源与证据边界</h3><ul class="source-links">${w.sources.map(s=>safeSource(s)).filter(Boolean).map((u,i)=>`<li><a href="${escape(u.href)}" target="_blank" rel="noopener noreferrer">${i+1}. ${escape(sourceLabel(u))} ↗</a></li>`).join('')}</ul><p>${escape(w.evidence_note)}</p></div><div class="detail-actions">${compareButton(w)}${w.research?`<a href="./report.html#record-${String(w.research.report_index).padStart(3,'0')}">查看研究报告记录 ↗</a>`:''}</div>`;
 $('work-detail').insertAdjacentHTML('beforeend',completionDetail(w));
 $('work-detail').insertAdjacentHTML('beforeend',`<div class="detail-section"><h3>实体身份与研究层</h3><p>${escape(w.entity_link?.status||'来源书目实体')} · ${escape(w.entity_link?JSON.stringify(w.entity_link.basis):'尚无可链接研究层')}。</p><p>空间：${escape(w.spatial_primary==='unknown'?'待分类（没有空间判断证据）':zone?.label||w.spatial_primary)}</p></div><div id="source-detail" class="detail-section">${w.source_id?'正在载入完整来源记录…':'该研究记录未可靠链接到本次来源查询，已独立保留。'}</div>`);
 if(!$('work-dialog').open)$('work-dialog').showModal();updateURL();if(w.source_id)renderSourceDetail(w,ticket);if(w.library_detail_url)renderLibraryDetail(w,ticket);
}
function closeWork(){detailTicket++;if($('work-dialog').open)$('work-dialog').close();selectedWork='';updateURL();}
function updateComparison(){
 $('compare-tray').hidden=!compareIds.length;$('compare-count').textContent=`已选 ${compareIds.length} / 3 部作品`;$('compare-titles').textContent=compareIds.map(id=>byId.get(id).title_zh).join(' · ');$('open-comparison').disabled=compareIds.length<2;
 document.querySelectorAll('[data-compare]').forEach(button=>{const active=compareIds.includes(button.dataset.compare);button.setAttribute('aria-pressed',String(active));button.textContent=active?'✓ 已加入比较':'+ 比较';button.setAttribute('aria-label',`${active?'从比较移除':'加入比较'}：${byId.get(button.dataset.compare)?.title_zh||''}`);});saveComparison();
}
function toggleCompare(id){id=aliases.get(id)||id;if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else if(compareIds.length>=3){showToast('最多同时比较 3 部作品，请先移除一部。');return;}else compareIds.push(id);updateComparison();}
function showComparison(){
 if(compareIds.length<2)return;closeWork();const selected=compareIds.map(id=>byId.get(id));
 const rows=[['补全与核对状态',w=>`待独立核对；${escape(w.completion?.missing_fields.map(k=>FIELD_LABELS[k]).join('、'))||'核心字段已有记录'}${w.knowledge?'；含已有知识补充':''}`],['底层问题',w=>escape(w.issue)],['细分问题',w=>w.issue_facets.map(f=>`<strong>${escape(f.label)}</strong><p>${escape(f.question)}</p><small>${escape(f.basis)} · 待核</small>`).join('')||'尚未补充'],['发表年份与形态',w=>`${escape(w.year_display)} · ${escape(w.form)}<small>${escape(w.year_note)}</small>`],['故事所在时代',w=>escape(w.story_era)],['主体叙事跨度',w=>escape(w.duration)],['最大时间视野',w=>escape(w.reach)],['底层议题',w=>w.topics.map(t=>tag(t)).join(' ')||'待分类'],['科幻分支',w=>w.branches.map(t=>tag(t,'branch')).join(' ')||'待分类'],['科学前提',w=>`${escape(w.science_class)}<small>${escape(w.science_note)}</small>`]];
 $('comparison-content').innerHTML=`<div class="table-scroll"><table class="comparison-table"><thead><tr><th scope="col">比较维度</th>${selected.map(w=>`<th scope="col">${escape(w.title_zh)}<small>${escape(w.author)}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([label,render])=>`<tr><th scope="row">${label}</th>${selected.map(w=>`<td>${render(w)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('comparison-dialog').showModal();
}
function showToast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function applyFilter(key,value){if(location.hash!=='#library')location.hash='library';closeWork();if($('comparison-dialog').open)$('comparison-dialog').close();state[key]=['yearMin','yearMax'].includes(key)?(value===''?null:Number(value)):value;if(key==='era'&&value){state.yearStatus='';state.yearMin=null;state.yearMax=null;}state.page=1;renderNavigation();updateFilters();renderLibrary();$('library-view').scrollIntoView({behavior:'smooth',block:'start'});}
function resetFilters(){state={...SITE_DEFAULT_STATE,layout:state.layout};updateFilters();renderLibrary();}
function clearFilter(key){closeWork();state[key]=['yearMin','yearMax'].includes(key)?null:'';state.page=1;updateFilters();renderLibrary();}
function registerEvents(){
 for(const key of ['level','space','yearStatus','audit','missing','issueStatus','facet'])$(`global-${key}`).addEventListener('change',e=>{state[key]=e.target.value;if(key==='yearStatus'&&state[key]==='unknown'){state.yearMin=null;state.yearMax=null;state.era='';}state.page=1;updateFilters();renderLibrary();});
 let searchTimer;$('global-search').addEventListener('input',e=>{clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{state.query=value;state.page=1;updateFilters();renderLibrary();},150);});$('global-reset').addEventListener('click',resetFilters);

 for(const key of Object.keys(filterNames))$(`filter-${key}`).addEventListener('change',e=>{state[key]=e.target.value;if(key==='era'&&state[key]){state.yearStatus='';state.yearMin=null;state.yearMax=null;}state.page=1;updateFilters();renderLibrary();});
 $('search-input').addEventListener('input',e=>{clearTimeout(searchTimer);state.query=e.target.value;state.page=1;updateFilters();renderLibrary();});$('search-form').addEventListener('submit',e=>e.preventDefault());
 for(const id of ['include-boundary','chronology-boundary'])$(id).addEventListener('change',e=>{state.boundary=e.target.checked;state.page=1;updateFilters();renderLibrary();});$('sort').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;renderLibrary();});$('reset-filters').addEventListener('click',resetFilters);$('chronology-reset').addEventListener('click',resetFilters);
 for(const layout of ['cards','table'])$(`${layout}-toggle`).addEventListener('click',()=>{state.layout=layout;renderLibrary();});
 for(const direction of ['previous','next'])$(`${direction}-page`).addEventListener('click',()=>{state.page+=direction==='next'?1:-1;renderLibrary();$('search-form').scrollIntoView({behavior:'smooth',block:'start'});});
 document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.work){if(!target.closest('#universe-root,#chronology-root'))openWork(target.dataset.work);}else if(target.dataset.compare)toggleCompare(target.dataset.compare);else if(target.dataset.filter)applyFilter(target.dataset.filter,target.dataset.value);else if(target.dataset.clear)clearFilter(target.dataset.clear);else if(target.hasAttribute('data-clear-years')){state.yearMin=null;state.yearMax=null;state.page=1;renderLibrary();}else if(target.hasAttribute('data-reset'))resetFilters();});
 $('close-work').addEventListener('click',closeWork);$('work-dialog').addEventListener('cancel',()=>{selectedWork='';updateURL();});$('close-comparison').addEventListener('click',()=>$('comparison-dialog').close());
 for(const id of ['work-dialog','comparison-dialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){id==='work-dialog'?closeWork():$(id).close();}}});
 $('clear-comparison').addEventListener('click',()=>{compareIds=[];updateComparison();});$('open-comparison').addEventListener('click',showComparison);
 addEventListener('hashchange',renderNavigation);addEventListener('popstate',()=>{const id=new URLSearchParams(location.search).get('work');selectedWork=id&&(byId.has(id)||aliases.has(id))?(aliases.get(id)||id):'';state=stateFromURL(location.search,works);if(!new URLSearchParams(location.search).has('boundary'))state.boundary=true;updateFilters();renderLibrary();renderNavigation();if(selectedWork)openWork(selectedWork);else closeWork();});
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('work-dialog').open&&!$('comparison-dialog').open){e.preventDefault();location.hash='library';renderNavigation();$('search-input').focus();}});
}
async function init(){try{
 const responses=await Promise.all(['catalog.json','content.json','spatial.json','research-links.json'].map(name=>fetch('./assets/'+name)));
 if(responses.some(r=>!r.ok))throw new Error('统一模型数据无法载入');
 const [catalog,navigation,spaceData,links]=await Promise.all(responses.map(r=>r.json()));
 catalog.works.forEach((w,i)=>w.report_index=i+1);
 const [source,completion]=await Promise.all([loadBibliographySource(),loadCompletionSource()]);sourceMetadata=source.metadata;
 const canonical=buildCanonicalUniverse(source.records,catalog.works,spaceData,links,completion.records);
 works=canonical.works;aliases=canonical.aliases;content=navigation;spatial=canonical.spatial;
 allCoverage=coverageOf(works);spatialById=new Map(spatial.works.map(w=>[w.id,w]));byId=new Map(works.map(w=>[w.id,w]));
 renderCompletion($('completion-root'),works,completion.metadata);setOptions('global-facet',unique(works.flatMap(w=>w.issue_facets.map(f=>f.label))));setOptions('global-missing',Object.entries(FIELD_LABELS).map(([id,label])=>({id,label})));

 state=stateFromURL(location.search,works);if(!new URLSearchParams(location.search).has('boundary'))state.boundary=true;compareIds=readComparison();
 setOptions('filter-topic',[...content.topics.map(t=>t.title),{id:'__unknown__',label:'议题待分类'}]);setOptions('filter-branch',unique(works.flatMap(w=>w.branches)));setOptions('filter-era',ERA_BOUNDS);setOptions('filter-duration',[...DURATIONS,{id:'__unknown__',label:'跨度待分类 / 待核'}]);setOptions('filter-science',[...SCIENCES,{id:'__unknown__',label:'科学前提待分类'}]);setOptions('filter-language',unique(works.flatMap(w=>w.languages)));setOptions('filter-form',unique(works.flatMap(w=>w.forms)));
 universe=mountUniverse($('universe-root'),{works,spatial,onWork:openWork,onTopic:value=>{state.topic=value;state.page=1;updateFilters();renderLibrary();},onReset:resetFilters,onZone:value=>{state.space=value==='all'?'':value;state.page=1;updateFilters();renderLibrary();},onTimeline:()=>{location.hash='chronology';renderNavigation();}});
 chronology=mountChronology($('chronology-root'),{works,onWork:openWork,onRange:(min,max)=>{state.yearMin=min;state.yearMax=max;state.yearStatus='';state.era='';state.page=1;updateFilters();renderLibrary();},onUnknownYear:()=>{state.yearStatus='unknown';state.yearMin=null;state.yearMax=null;state.era='';state.page=1;updateFilters();renderLibrary();}});
 bibliography=mountBibliography($('bibliography-root'),{onWork:openWork,onChange:patch=>{Object.assign(state,patch);state.page=1;updateFilters();renderLibrary();}});
 taxonomy=mountTaxonomy($('taxonomy-root'),{onGenre:label=>{const genre=works.flatMap(w=>w.source_subject).find(g=>g.label===label);state.genre=genre?.id||label;state.page=1;updateFilters();renderLibrary();location.hash='bibliography';renderNavigation();}});
 fetch('./assets/genre-hierarchy.json').then(r=>{if(!r.ok)throw new Error('分支谱系无法载入');return r.json();}).then(graph=>{genreGraph=graph;taxonomy.update(graph,filterWorks(works,state));}).catch(error=>{$('taxonomy-root').querySelector('.taxonomy-summary').textContent=error.message;});
 const requestedWork=new URLSearchParams(location.search).get('work');updateFilters();renderContent();registerEvents();renderNavigation();renderLibrary();updateComparison();if(requestedWork)openWork(requestedWork);
 $('coverage-summary').textContent=`统一记录 ${works.length.toLocaleString('zh-CN')}；已有研究 ${allCoverage.researched}；核心问题分析 ${allCoverage.issue_analyzed}；细分问题 ${allCoverage.issue_facets} 项；议题待分类 ${allCoverage.topic_unknown.toLocaleString('zh-CN')}；年份未知 ${allCoverage.year_unknown.toLocaleString('zh-CN')}；空间待分类 ${allCoverage.space_unknown.toLocaleString('zh-CN')}；已有知识补充 ${allCoverage.knowledge_added}；部分书目跨来源对应 ${allCoverage.library_correspondence}。`;
}catch(error){$('global-count').textContent='全量数据未完成载入';$('universe-root').innerHTML='<div class="empty-state"><h2>完整底库暂时无法载入</h2><p>请刷新页面重试；没有将部分索引当作完整底库展示。</p><a href="./report.html">阅读已有研究报告 ↗</a></div>';$('result-count').textContent='统一底库暂时无法载入';$('results').innerHTML='<div class="error-panel"><p>完整底库未载入成功，未展示部分数据。请刷新重试。</p><a href="./report.html">阅读已有研究报告 ↗</a></div>';console.error(error);}}
async function renderSourceDetail(w,ticket){
 try{const record=await loadSourceDetail(w);if(ticket!==detailTicket||selectedWork!==w.id||!$('work-dialog').open)return;
 const relationships=Object.entries(record.relationships||{}).filter(([,values])=>values.length).map(([property,values])=>`<p><strong>${escape(({P179:'系列',P361:'属于',P155:'前作',P156:'后作',P144:'基于',P747:'版本'})[property]||property)} / ${escape(property)}</strong>：${values.map(v=>{const title=v.labels?.['zh-hans']||v.labels?.zh||v.labels?.en||v.id;return byId.has(v.id)?`<button class="anchor-link" data-work="${escape(v.id)}">${escape(title)} · ${escape(v.id)}</button>`:`<a href="https://www.wikidata.org/wiki/${escape(v.id)}" target="_blank" rel="noopener noreferrer">${escape(title)} · ${escape(v.id)} ↗</a>`;}).join('；')}</p>`).join('');
 $('source-detail').innerHTML=`<h3>完整来源书目与分类依据</h3><p>${escape(record.description_zh||record.description_en||'来源描述未知')}</p><p>全部出版日期：${escape((record.publication_dates||[]).join('；')||'未知')}。原语与初刊尚待核验。</p><p>原始分支：${escape(w.source_subject.map(v=>v.label+' / '+v.id).join('；')||'未提供')}</p><p>来源语言声明：${escape((record.language_statements||[]).map(v=>v.label+' / '+v.id).join('；')||'未知')}</p><h4>系列、前后作与版本关系</h4>${relationships||'<p>来源未提供关系。</p>'}<details><summary>候选议题全部依据（${record.topic_candidates?.length||0} 项）</summary><pre>${escape(JSON.stringify(record.topic_candidates||[],null,2))}</pre></details><details><summary>完整来源字段与结构化记录</summary><pre>${escape(JSON.stringify(record,null,2))}</pre></details><details><summary>已有研究层与实体链接依据</summary><pre>${escape(JSON.stringify({research:w.research,link:w.entity_link},null,2))}</pre></details>`;
 }catch(error){if(ticket===detailTicket&&selectedWork===w.id&&$('work-dialog').open)$('source-detail').innerHTML=`<p>${escape(error.message)}</p><button data-retry-detail="${escape(w.id)}">重试完整来源详情</button>`;}
}
document.addEventListener('click',e=>{const id=e.target.closest('[data-retry-detail]')?.dataset.retryDetail;if(id)renderSourceDetail(byId.get(id),detailTicket);});
init();

async function renderLibraryDetail(w,ticket){try{const r=await loadLibraryDetail(w);if(ticket!==detailTicket||selectedWork!==w.id||!$('work-dialog').open)return;$('library-detail').innerHTML=`<details><summary>全部外部书目字段与主题词依据</summary><p>主题词是书目标签，译本语言不是原语；不据此推测主体叙事时长或空间位置。</p><pre>${escape(JSON.stringify(r,null,2))}</pre></details>`;}catch(error){if(ticket===detailTicket&&selectedWork===w.id&&$('work-dialog').open)$('library-detail').innerHTML=`<p>${escape(error.message)}</p><button data-retry-library="${escape(w.id)}">重试外部详情</button>`;}}
document.addEventListener('click',e=>{const id=e.target.closest('[data-retry-library]')?.dataset.retryLibrary;if(id)renderLibraryDetail(byId.get(id),detailTicket);});
